using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class SocialAssetTests
{
 static readonly EntityId Other=new("created:social-b"),Third=new("created:social-c");
 static WorldSession Start(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer("created:social-a"),NewGameWorldTests.Officer(Other.Value),NewGameWorldTests.Officer(Third.Value)]);return new(NewGameWorld.Create(setup.World,setup.Registered,"created:social-a",42,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,economyPolicy:MaterialMarkets.Policy));}
 static EntityId Here(WorldSession s)=>SocialWorld.Site(s.DiagnosticSnapshot(),s.PlayerControl)!.Value;
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 static SocialAssetInput Input(WorldSession s,SocialAssetAction action,EntityId? person=null,EntityId? reference=null,long when=0)=>new(new("request:assets/"+s.Revision),action,person??s.PlayerControl,reference,when);
 static void Act(WorldSession s,SocialAssetAction action,EntityId? person=null,EntityId? reference=null,long when=0)=>Good(s.ManageSocialAsset(Input(s,action,person,reference,when),s.Revision));
 static void Visit(WorldSession s,EntityId person)=>Good(s.ManageSocial(new(new("request:assets-meet/"+s.Revision),SocialWorldAction.Visit,person),s.Revision));
 static void Give(WorldSession s,EntityId item,EntityId? person=null)=>Good(s.ManageSocial(new(new("request:assets-gift/"+s.Revision),SocialWorldAction.DispatchGift,person??Other){Asset=item},s.Revision));
 static EntityId Buy(WorldSession s,string kind="tea"){var a=SocialAssets.Catalog(s.DiagnosticSnapshot(),Here(s)).Single(a=>a.Kind==kind);Act(s,SocialAssetAction.Buy,reference:a.Id);return a.Id;}
 [Fact]public void UniqueObjectUsesRealMoneyAndCannotBeBoughtTwice(){var s=Start();long before=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);var a=Buy(s);Assert.Equal(before-180,NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl));Assert.Equal(180,SocialAssets.MerchantReceipts(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.ManageSocialAsset(Input(s,SocialAssetAction.Buy,reference:a),s.Revision).Code);Assert.Single(SocialAssets.Inventory(s.DiagnosticSnapshot(),s.PlayerControl));}
 [Fact]public void UniqueGiftTransfersOneOwnerAndPreservesProvenance(){var s=Start();var id=Buy(s);Give(s,id);var w=s.DiagnosticSnapshot();var o=SocialAssets.Objects(w).Single();Assert.Equal(Other,o.Owner);Assert.Equal(Other,o.Holder);Assert.Contains(o.History,h=>h.Contains("受領"));Assert.Empty(SocialAssets.Inventory(w,s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,s.ManageSocial(new(new("request:duplicate-object"),SocialWorldAction.DispatchGift,Third){Asset=id},s.Revision).Code);}
 [Theory][InlineData(null)][InlineData("wood")][InlineData("weapons")]
 public void ExistingPrivateGoodsBecomeGiftAndCannotAlsoBeSold(string? kind){var s=Start();var site=Here(s);var quote=new TradeInput(new("request:asset-quote"),TradeAction.Quote,site,Destination:site,Amount:5){Commodity=kind};Good(s.TradeRice(quote,s.PlayerControl,s.Revision));var id=s.DiagnosticSnapshot().Trade!.Deals.Single().Id;foreach(var action in new[]{TradeAction.Accept,TradeAction.Collect})Good(s.TradeRice(new(new("request:asset-buy/"+action),action,site,id),s.PlayerControl,s.Revision));long money=NewGameWork.Balance(s.DiagnosticSnapshot(),s.PlayerControl);Give(s,id);var w=s.DiagnosticSnapshot();Assert.Equal(TradePhase.Gifted,w.Trade!.Deals.Single().Phase);Assert.Equal(5,SocialAssets.Inventory(w,Other).Single().Quantity);Assert.Equal(money,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:asset-resale"),TradeAction.OfferSale,site,id),s.PlayerControl,s.Revision).Code);Assert.Equal(ContractJson.Write(w),ContractJson.Write(new WorldSession(ContractJson.Copy(w)).DiagnosticSnapshot()));}
 [Fact]public void DirectExportAndForgedObjectCannotCreateGoods(){var s=Start();Assert.Equal(ResultCode.NotAvailable,s.TradeRice(new(new("request:illegal-export"),TradeAction.GiftOut,Here(s),new("request:none")),s.PlayerControl,s.Revision).Code);var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.ManageSocial(new(new("request:nonexistent-object"),SocialWorldAction.DispatchGift,Other){Asset=new("object:invented")},s.Revision).Code);Assert.Equal(raw,ContractJson.Write(s.DiagnosticSnapshot()));}
 [Fact]public void IntroductionRequiresTheWritersActualKnowledgeAndIsSingleUse(){var s=Start();Visit(s,Other);var i=Input(s,SocialAssetAction.DraftIntroduction,Other,Third);Assert.Equal(ResultCode.NotAvailable,s.ManageSocialAsset(i,s.Revision).Code);var w=s.DiagnosticSnapshot();w.CommitSequence++;SocialWorld.Execute(w,new(new("request:writer-met-target"),SocialWorldAction.Visit,Third),Other);s=new(w);i=Input(s,SocialAssetAction.DraftIntroduction,Other,Third);Good(s.ManageSocialAsset(i,s.Revision));Assert.DoesNotContain(SocialWorld.Facts(s.DiagnosticSnapshot(),s.PlayerControl,Third),f=>f.Description.Contains("紹介"));Act(s,SocialAssetAction.PresentIntroduction,Third,i.Id);Assert.Contains(SocialWorld.Facts(s.DiagnosticSnapshot(),s.PlayerControl,Third),f=>f.Description.Contains("紹介"));Assert.Equal(ResultCode.NotAvailable,s.ManageSocialAsset(Input(s,SocialAssetAction.PresentIntroduction,Third,i.Id),s.Revision).Code);}
 static EntityId Invite(WorldSession s,EntityId guest,long when,EntityId? tea=null){Visit(s,guest);var i=Input(s,SocialAssetAction.PlanTea,guest,tea,when);Good(s.ManageSocialAsset(i,s.Revision));return i.Id;}
 [Fact]public void InvitationMustArriveBeforeNpcAgrees(){var s=Start();var plan=Invite(s,Other,3600);Assert.DoesNotContain(s.DiagnosticSnapshot().SocialAssets!.Events,e=>e.Input.Action==SocialAssetAction.AcceptTea);Give(s,plan);Assert.Contains(s.DiagnosticSnapshot().SocialAssets!.Events,e=>e.Input.Action==SocialAssetAction.AcceptTea&&e.Actor==Other);Assert.DoesNotContain(SocialWorld.Facts(s.DiagnosticSnapshot(),s.PlayerControl,Other),f=>f.Description.Contains("茶会"));}
 [Fact]public void TeaCreatesFactsAmongActualGuestsAndSameFutureAfterRealSave(){var s=Start();var tea=Buy(s);var a=Invite(s,Other,3600,tea);Give(s,a);var b=Invite(s,Third,3600,tea);Give(s,b,Third);NewGameWorldTests.At(s,3600);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"social-assets-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"tea",w.WorldId).Published);var host=new WorldSessionHost(new(Start().DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("tea"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current})Act(x,SocialAssetAction.HoldTea,reference:a);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));w=s.DiagnosticSnapshot();Assert.Contains(SocialWorld.Facts(w,Other,Third),f=>f.Description.Contains("茶会"));Assert.Contains(SocialWorld.Renown(w,Third),f=>f.Kind==RenownKind.Culture&&f.Subject==s.PlayerControl);Assert.Equal(15,SocialAssets.HospitalityExpense(w));Act(s,SocialAssetAction.Buy,reference:SocialAssets.Catalog(w,Here(s)).Single(a=>a.Kind=="book").Id);Assert.Equal(ResultCode.NotAvailable,s.ManageSocialAsset(Input(s,SocialAssetAction.HoldTea,reference:b),s.Revision).Code);}
 [Fact]public void TeaCannotBeHeldBeforeTheTimeOrWithoutArrivingGuests(){var s=Start();var plan=Invite(s,Other,3600);Assert.Equal(ResultCode.NotAvailable,s.ManageSocialAsset(Input(s,SocialAssetAction.HoldTea,reference:plan),s.Revision).Code);NewGameWorldTests.At(s,3600);Assert.Equal(ResultCode.NotAvailable,s.ManageSocialAsset(Input(s,SocialAssetAction.HoldTea,reference:plan),s.Revision).Code);}
 [Fact]public void ForbiddenRosterCannotBeSuppliedByTheCaller(){var s=Start();var i=Input(s,SocialAssetAction.HoldTea) with{People=[s.PlayerControl,Other]};Assert.Equal(ResultCode.NotAvailable,s.ManageSocialAsset(i,s.Revision).Code);}
 [Fact]public void LegacySocialSaveKeepsBytesAndNoImplicitAssets(){var s=new WorldSession(SocialWorldTests.Start());Visit(s,Other);var raw=ContractJson.Write(s.DiagnosticSnapshot());Assert.DoesNotContain("SocialAssets",System.Text.Encoding.UTF8.GetString(raw));var restored=new WorldSession(ContractJson.Read<ContractWorld>(raw));Assert.Equal(raw,ContractJson.Write(restored.DiagnosticSnapshot()));}
 [Fact]public void ObjectRefusalReturnsTheSameObjectWithoutChangingMoney(){var s=Start();var id=Buy(s);var w=s.DiagnosticSnapshot();w.CommitSequence++;SocialWorld.Execute(w,new(new("request:incoming-object"),SocialWorldAction.DispatchGift,Other){Asset=id},s.PlayerControl); // NPC自動応答前の荷
  Assert.Equal(s.PlayerControl,SocialAssets.Objects(w).Single().Owner);w.CommitSequence++;SocialWorld.Execute(w,new(new("request:reject-object"),SocialWorldAction.RefuseGift,s.PlayerControl,Reference:new("request:incoming-object")),Other);w.CommitSequence++;SocialWorld.Execute(w,new(new("request:return-object"),SocialWorldAction.ReturnGift,s.PlayerControl,Reference:new("request:incoming-object")),s.PlayerControl);Assert.Equal(s.PlayerControl,SocialAssets.Inventory(w,s.PlayerControl).Single().Owner);Assert.Equal(820,NewGameWork.Balance(w,s.PlayerControl));Assert.Equal(1000,NewGameWork.Balance(w,Other));ContractValidation.Validate(w);
 }
 [Fact]public void NpcHostsAndActuallyHoldsTheSameLocalTea(){var s=Start();Visit(s,Other);Buy(s);NewGameWorldTests.At(s,86400);var w=s.DiagnosticSnapshot();var plan=w.SocialAssets!.Events.First(e=>e.Input.Action==SocialAssetAction.PlanTea&&e.Actor!=s.PlayerControl);if(plan.Input.Person==s.PlayerControl){var g=w.SocialWorld!.Events.Single(e=>e.Input.Asset==plan.Input.Id&&e.Input.Action==SocialWorldAction.DispatchGift);Good(s.ManageSocial(new(new("request:accept-invitation-envelope"),SocialWorldAction.ReceiveGift,g.Actor,Reference:g.Input.Id),s.Revision));Act(s,SocialAssetAction.AcceptTea,plan.Actor,plan.Input.Id);}NewGameWorldTests.At(s,plan.Input.When);Assert.Contains(s.DiagnosticSnapshot().SocialAssets!.Events,e=>e.Input.Action==SocialAssetAction.HoldTea&&e.Actor==plan.Actor);}
 [Fact]public void ForgedDuplicatePurchaseCannotLoad(){var s=Start();Buy(s);var w=s.DiagnosticSnapshot();var e=w.SocialAssets!.Events.Single();w.SocialAssets=w.SocialAssets with{Events=[e,e with{Input=e.Input with{Id=new("request:forged-purchase")}}]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}

}
